import{_ as a,C as s,o as n,c as l,a2 as t,E as r}from"./chunks/framework.BSaF8iZ6.js";const m=JSON.parse('{"title":"Selling Existing Products","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/selling-existing-products.md","filePath":"catalog/selling-existing-products.md","lastUpdated":1789411447000}'),i={name:"catalog/selling-existing-products.md"};function d(c,o,u,g,p,h){const e=s("ImagePopup");return n(),l("div",null,[o[0]||(o[0]=t('<h1 id="selling-existing-products" tabindex="-1">Selling Existing Products <a class="header-anchor" href="#selling-existing-products" aria-label="Permalink to &quot;Selling Existing Products&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span></div><p>When a product is already in the store&#39;s catalog, you don&#39;t need to create it again. You can sell it as your own, with your own price, stock, condition and description. The product&#39;s name, images and details stay as they are in the catalog.</p><p>Customers see your offer next to other sellers&#39; offers for the same product. See <a href="./../storefront/shopping-across-sellers">Shopping Across Sellers</a>.</p><h2 id="find-the-product" tabindex="-1">Find the product <a class="header-anchor" href="#find-the-product" aria-label="Permalink to &quot;Find the product&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; List Your Product</strong>.</li><li>Click <strong>Search Products</strong>.</li><li>Type at least three letters of the product name.</li><li>Click <strong>Sell as Yours</strong> on the product you want.</li></ol>',6)),r(e,{src:"/images/selling-existing-products/search.png",alt:"Search results with the Sell as Yours link"}),o[1]||(o[1]=t('<p>You can&#39;t sell a product when:</p><ul><li>the store doesn&#39;t allow sellers to sell catalog products (<strong>You are not allowed to assign this product</strong>);</li><li>you already sell it (<strong>You are already selling this product</strong>);</li><li>its product type isn&#39;t one you&#39;re allowed to sell.</li></ul><h2 id="create-your-offer" tabindex="-1">Create your offer <a class="header-anchor" href="#create-your-offer" aria-label="Permalink to &quot;Create your offer&quot;">​</a></h2><ol><li>On <strong>Assign Product</strong>, choose the <strong>Condition</strong>: <strong>New</strong> or <strong>Old</strong>.</li><li>Enter your <strong>Price</strong>. For a product with variations, you set it for each variant instead.</li><li>Enter a <strong>Description</strong> of your offer, up to 300 characters.</li><li>Under <strong>Inventories</strong>, enter how many you have in each inventory source. This appears for simple and virtual products only.</li><li>Click <strong>Submit</strong>, or <strong>Save as Draft</strong> to finish later.</li></ol>',4)),r(e,{src:"/images/selling-existing-products/assign-form.png",alt:"The Assign Product form for selling a catalog product"}),o[2]||(o[2]=t('<p><strong>Product Details</strong> on the right shows the catalog product you are selling. The <strong>Condition</strong>, <strong>Price</strong> and <strong>Description</strong> are needed when you submit, but you can leave them empty in a draft.</p><p>You&#39;ll see <strong>Product assigned successfully to the seller</strong>. If the store approves products, your offer waits for approval like any other product. See <a href="./product-approval">Product Approval</a>.</p><h3 id="products-with-variations" tabindex="-1">Products with variations <a class="header-anchor" href="#products-with-variations" aria-label="Permalink to &quot;Products with variations&quot;">​</a></h3><p>For a product that comes in sizes or colours, you choose which variants to sell. For each one, set its <strong>Price</strong>, <strong>Quantities</strong>, <strong>Description</strong> and <strong>Images</strong>. The condition you choose applies to all of them.</p><h3 id="downloadable-products" tabindex="-1">Downloadable products <a class="header-anchor" href="#downloadable-products" aria-label="Permalink to &quot;Downloadable products&quot;">​</a></h3><p>For a downloadable product, add your own <strong>Downloadable Links</strong> and <strong>Downloadable Samples</strong>.</p><h2 id="update-or-remove-your-offer" tabindex="-1">Update or remove your offer <a class="header-anchor" href="#update-or-remove-your-offer" aria-label="Permalink to &quot;Update or remove your offer&quot;">​</a></h2><ul><li>To change the price, stock or condition, open the product from <strong>Catalog &gt;&gt; Products</strong> and click <strong>Save</strong>.</li><li>To stop selling it, delete it from <strong>Catalog &gt;&gt; Products</strong>. Only your offer is removed. The catalog product stays in the store.</li></ul><p>To change prices or stock for many products at once, use <a href="./../pricing/manage-pricing">Manage Pricing</a> and <a href="./../inventory/manage-inventory">Manage Inventory</a>.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><ul><li>Your offer uses the catalog product&#39;s images. Only the variants of a product with variations can have their own images.</li><li>To sell many catalog products at once, use <strong>Sell Catalog Products</strong> in <a href="./bulk-upload">Bulk Upload</a>.</li><li>If the store uses subscription plans, your offers count towards your plan&#39;s product limit.</li><li>The store admin can also add a catalog product to your shop for you. See <a href="./../sellers/seller-management#assign-a-product-to-a-seller">Seller Management</a>.</li></ul>',11))])}const y=a(i,[["render",d]]);export{m as __pageData,y as default};
